<?php require_once __DIR__.'/../includes/functions.php';$u=require_login();verify_csrf();$id=(int)$u['id'];$days=implode(',',array_intersect($_POST['days']??[],['Mon','Tue','Wed','Thu','Fri','Sat','Sun']));$avatar=null;if(!empty($_FILES['avatar']['name'])){$f=$_FILES['avatar'];if($f['error']!==UPLOAD_ERR_OK||$f['size']>2097152){flash('danger','Image upload failed or exceeds 2 MB.');go('../student/edit-profile.php');}$mime=(new finfo(FILEINFO_MIME_TYPE))->file($f['tmp_name']);$types=['image/jpeg'=>'jpg','image/png'=>'png','image/webp'=>'webp'];if(!isset($types[$mime])||!getimagesize($f['tmp_name'])){flash('danger','Please choose a valid JPG, PNG, or WEBP image.');go('../student/edit-profile.php');}$avatar=bin2hex(random_bytes(16)).'.'.$types[$mime];if(!move_uploaded_file($f['tmp_name'],__DIR__.'/../uploads/profiles/'.$avatar)){flash('danger','Could not save the uploaded image.');go('../student/edit-profile.php');}}$pdo=db();$pdo->beginTransaction();try{$sql='UPDATE users SET name=? WHERE id=?';$pdo->prepare($sql)->execute([trim($_POST['name']??$u['name']),$id]);$q='UPDATE student_profiles SET college=?,course=?,semester=?,about=?,learning_goals=?,study_mode=?,availability_days=?,start_time=?,end_time=?,languages=?'.($avatar?',avatar=?':'').' WHERE user_id=?';$vals=[trim($_POST['college']??''),trim($_POST['course']??''),($_POST['semester']??'')?:null,trim($_POST['about']??''),trim($_POST['learning_goals']??''),in_array($_POST['study_mode']??'', ['Online','Offline','Both'])?$_POST['study_mode']:null,$days,$_POST['start_time']?:null,$_POST['end_time']?:null,trim($_POST['languages']??'')];if($avatar)$vals[]=$avatar;$vals[]=$id;$pdo->prepare($q)->execute($vals);$pdo->prepare('DELETE FROM user_skills WHERE user_id=?')->execute([$id]);foreach(array_unique(array_map('intval',$_POST['skills']??[])) as $sid)$pdo->prepare('INSERT IGNORE INTO user_skills(user_id,skill_id) VALUES(?,?)')->execute([$id,$sid]);$pdo->prepare('DELETE FROM user_subjects WHERE user_id=?')->execute([$id]);foreach(['help','want'] as $intent)foreach(array_unique(array_map('intval',$_POST['subjects'][$intent]??[])) as $sid)$pdo->prepare('INSERT IGNORE INTO user_subjects(user_id,subject_id,intent) VALUES(?,?,?)')->execute([$id,$sid,$intent]);$pdo->commit();flash('success','Your profile has been updated.');go('../student/profile.php');}catch(Throwable $e){$pdo->rollBack();flash('danger','We could not save your profile. Please check your selections.');go('../student/edit-profile.php');}
